424	\begin{lemma}[Preservation of the robustness error family]\label{lem:qld-extraction-error-form}
425		\lean{MIPStarRE.QPBT.deltaExtract_le_deltaQld}
426		\uses{def:admissible, lem:qld-unitary}
427		Let $C\geq1$, $a>1$, and $0<b<1$. Suppose that
428		\[
429			\delta_G=a(md)^a\bigl(\eps^b+q^{-b}+2^{-bmd}\bigr),
430			\qquad
431			\delta_P=C\left(\delta_G+\sqrt{\eps}+\frac{md}{q}\right),
432		\]
433		and set $\delta_{\mathrm{ext}}=C(\delta_P^{1/4}+md/q)$. There are constants
434		$a'\geq1$ and $0<b'<1$, depending only on $C,a,b$, such that, for every
435		admissible $(q,m,d)$ and every $0\leq\eps\leq1$,
436		\[
437			\delta_{\mathrm{ext}}
